import (
	"testing"
	"time"
)

// An OnChange callback that takes a lock the store's caller may hold, or
// that calls back into the store, must not deadlock the store. The
// notifier does exactly this: it holds its own mutex while calling the
// store, and its change callback takes that mutex.
func TestOnChangeMayUseStore(t *testing.T) {
	s := newStore()
	r := s.Create("u1", "a", t0, nil)
	s.OnChange(func(*Reminder) {
		// Reads the store from inside the callback.
		s.Count("u1")
	})

	done := make(chan error, 1)
	go func() {
		done <- s.Update(r.ID, func(r *Reminder) error { r.Done = true; return nil })
	}()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Update deadlocked: OnChange callback re-entered the store")
	}
}
"}

