// deleteUser removes the user and tombstones their reminders, returning
// the reminders that changed.
func (s *Store) deleteUser(id string) ([]*Reminder, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	if !ok {
		return nil, ErrNotFound
	}
	delete(s.users, id)
	delete(s.tokens, u.Token)
	var changed []*Reminder
	for _, r := range s.byUser[id] {
		r.Deleted = true
		changed = append(changed, r)
	}
	return changed, nil
